def solve(inputs: dict) -> float:
    M = inputs['matrix']
    power = inputs['power']
    mod_val = inputs['mod_value']

    def matrix_mult(A, B):
        return [[sum(a * b for a, b in zip(A_row, B_col)) % mod_val for B_col in zip(*B)] for A_row in A]

    result = [[1, 0], [0, 1]]
    base = M

    while power > 0:
        if (power % 2) == 1:
            result = matrix_mult(result, base)
        base = matrix_mult(base, base)
        power //= 2

    return sum(sum(row) for row in result)
